using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "SampleDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change: The Cosmos provider now uses
            // "$type" instead of "Discriminator" for the discriminator property.
            // Existing documents still have "Discriminator", so we must explicitly
            // configure the old property name for backward compatibility.
            entity.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

using Microsoft.EntityFrameworkCore;

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O is no longer supported by the
    // Cosmos DB provider. All queries must use async methods (ToListAsync, etc.).
    // The sync methods (ToList, First, etc.) now throw InvalidOperationException.
    async Task<List<Product>> GetProductsByCategoryAsync(CosmosDbContext db, string category)
    {
        return await db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    async Task<Product?> GetProductByIdAsync(CosmosDbContext db, string id)
    {
        return await db.Products.FirstOrDefaultAsync(p => p.Id == id);
    }
}

